</template>

<script setup>
import { ref, onUnmounted, nextTick } from 'vue';

// 摄像头相关状态
const videoRef = ref(null);
const canvasRef = ref(null);
const isCameraActive = ref(false);
const isDetecting = ref(false);
const detectionInterval = ref(null);
const streamRef = ref(null);
const detectionStartTime = ref(null); // 记录检测开始时间

// 检测结果
const detections = ref([]); // 当前帧的检测结果
const allDetections = ref([]); // 记录所有帧的检测结果
const isLoading = ref(false);
const errorMessage = ref('');
const isExporting = ref(false); // 导出状态

// 动态加载SheetJS库
const loadSheetJS = async () => {
  if (window.XLSX) return Promise.resolve(window.XLSX);
  
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
    script.onload = () => resolve(window.XLSX);
    script.onerror = (err) => reject(err);
    document.head.appendChild(script);
  });
};

// 启动摄像头
const startCamera = async () => {
  try {
    streamRef.value = await navigator.mediaDevices.getUserMedia({ 
      video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'environment' } 
    });
    await nextTick();
    if (videoRef.value) {
      videoRef.value.srcObject = streamRef.value;
      videoRef.value.onloadedmetadata = () => {
        if (canvasRef.value) {
          canvasRef.value.width = videoRef.value.videoWidth;
          canvasRef.value.height = videoRef.value.videoHeight;
        }
      };
    }
    isCameraActive.value = true;
    errorMessage.value = '';
  } catch (error) {
    errorMessage.value = `Camera start failed: ${error.message}`;
    isCameraActive.value = false;
  }
};

// 停止摄像头
const stopCamera = () => {
  if (streamRef.value) {
    streamRef.value.getTracks().forEach(track => track.stop());
    streamRef.value = null;
  }
  if (videoRef.value) videoRef.value.srcObject = null;
  toggleDetection(false);
  isCameraActive.value = false;
  // 保留历史数据，不清除
};

// 切换检测
const toggleDetection = (forceState = null) => {
  const newState = forceState !== null ? forceState : !isDetecting.value;
  if (newState && !isDetecting.value) {
    // 开始检测时记录开始时间并清空历史数据
    detectionStartTime.value = new Date();
    allDetections.value = [];
    isDetecting.value = true;
    detectFromCamera();
    detectionInterval.value = setInterval(detectFromCamera, 2000);
  } else if (!newState && isDetecting.value) {
    isDetecting.value = false;
    if (detectionInterval.value) {
      clearInterval(detectionInterval.value);
      detectionInterval.value = null;
    }
  }
};

// 从摄像头检测
const detectFromCamera = async () => {
  if (!isCameraActive.value || !videoRef.value || !canvasRef.value) return;
  if (isLoading.value) return;

  try {
    isLoading.value = true;
    const ctx = canvasRef.value.getContext('2d');
    ctx.drawImage(videoRef.value, 0, 0, canvasRef.value.width, canvasRef.value.height);
    canvasRef.value.toBlob(async (blob) => {
      if (!blob) return;
      const formData = new FormData();
      formData.append('image', blob, 'camera-frame.jpg');
      const response = await fetch('https://123.56.203.202:8082/detect', { method: 'POST', body: formData });
      const data = await response.json();
      
      // 记录当前时间作为该帧检测的时间戳
      const detectionTime = new Date();
      
      // 更新当前帧的检测结果
      detections.value = data.detections || [];
      
      // 保存所有检测结果到历史记录，添加时间戳
      if (detections.value.length > 0) {
        const resultsWithTimestamp = detections.value.map(detection => ({
          ...detection,
          timestamp: detectionTime.toISOString(),
          frameNumber: allDetections.value.length + 1
        }));
        
        allDetections.value.push(...resultsWithTimestamp);
      }
      
      drawDetectionBoxes(detections.value);
    }, 'image/jpeg');
  } catch (err) {
    errorMessage.value = `Detection error: ${err.message}`;
  } finally {
    isLoading.value = false;
  }
};

// 画框
const drawDetectionBoxes = (detections) => {
  if (!canvasRef.value || !videoRef.value) return;
  const ctx = canvasRef.value.getContext('2d');
  ctx.drawImage(videoRef.value, 0, 0, canvasRef.value.width, canvasRef.value.height);
  detections.forEach(obj => {
    const [x1, y1, x2, y2] = obj.box;
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
    ctx.fillStyle = '#3b82f6';
    const label = `${obj.class} (${obj.confidence.toFixed(2)})`;
    const textMetrics = ctx.measureText(label);
    ctx.fillRect(x1, y1 - 20, textMetrics.width + 10, 20);
    ctx.fillStyle = 'white';
    ctx.font = '14px Arial';
    ctx.fillText(label, x1 + 5, y1 - 5);
  });
};

// 导出为XLS文件 - 包含从开始检测到当前的所有结果
const exportToXLS = async () => {
  if (allDetections.value.length === 0) return;
  
  try {
    isExporting.value = true;
    
    // 加载SheetJS库
    const XLSX = await loadSheetJS();
    
    // 准备导出数据 - 包含所有帧的检测结果
    const exportData = allDetections.value.map((detection, index) => ({
      'Record ID': index + 1,
      'Frame Number': detection.frameNumber,
      'Timestamp': new Date(detection.timestamp).toLocaleString(),
      'Class': detection.class,
      'Confidence': detection.confidence.toFixed(4),
      'X1': detection.box[0].toFixed(2),
      'Y1': detection.box[1].toFixed(2),
      'X2': detection.box[2].toFixed(2),
      'Y2': detection.box[3].toFixed(2),
      'Width': (detection.box[2] - detection.box[0]).toFixed(2),
      'Height': (detection.box[3] - detection.box[1]).toFixed(2),
      'Area': ((detection.box[2] - detection.box[0]) * (detection.box[3] - detection.box[1])).toFixed(2)
    }));
    
    // 创建工作簿和工作表
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'All_Cucumber_Detections');
    
    // 设置列宽
    const wscols = [
      {wch: 8},   // Record ID
      {wch: 12},  // Frame Number
      {wch: 20},  // Timestamp
      {wch: 10},  // Class
      {wch: 12},  // Confidence
      {wch: 10},  // X1
      {wch: 10},  // Y1
      {wch: 10},  // X2
      {wch: 10},  // Y2
      {wch: 10},  // Width
      {wch: 10},  // Height
      {wch: 10}   // Area
    ];
    worksheet['!cols'] = wscols;
    
    // 生成文件名（基于检测开始时间）
    const dateStr = detectionStartTime.value 
      ? detectionStartTime.value.toISOString().slice(0,19).replace(/:/g,'-')
      : new Date().toISOString().slice(0,19).replace(/:/g,'-');
    const fileName = `all_camera_detections_${dateStr}.xls`;
    
    // 导出文件
    XLSX.writeFile(workbook, fileName);
    
  } catch (error) {
    console.error('Export error:', error);
    errorMessage.value = `Export failed: ${error.message}`;
  } finally {
    isExporting.value = false;
  }
};

const formatBox = (box) => box.map(coord => coord.toFixed(2)).join(', ');
onUnmounted(() => stopCamera());
</script>

