import { createRouter, createWebHistory } from 'vue-router';
import WordPreview from './views/Image.vue';
import ChoosePerson from "./views/Folder.vue";
import BidDocument from "@/views/Camera.vue";
import VideoPreview from "@/views/Video.vue";
import ResultsView from "@/views/Results.vue"; // 导入Results视图组件

const routes = [
    { path: '/image', component: WordPreview },
    { path: '/folder', component: ChoosePerson },
    { path: '/camera', component: BidDocument },
    { path: '/video', component: VideoPreview },
    { path: '/results', component: ResultsView } // 添加results路由
];

const router = createRouter({
    history: createWebHistory(),
    routes,
});

export default router;
    